import XCTest

final class DumpTests: XCTestCase {
    func testDump() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        _ = app.wait(for: .runningForeground, timeout: 10)
        sleep(2)
        var lines: [String] = []
        lines.append("state=\(app.state.rawValue) exists=\(app.exists)")
        let all = app.descendants(matching: .any).allElementsBoundByIndex
        for e in all {
            let l = e.label
            let id = e.identifier
            if l.isEmpty && id.isEmpty { continue }
            lines.append("\(e.elementType.rawValue)|\(l)|\(id)|\(e.frame)")
        }
        let out = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-irkdlunc/tree.txt"
        try lines.joined(separator: "\n").write(toFile: out, atomically: true, encoding: .utf8)
    }
}
EOF
